def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h > 0 else 0

    from collections import Counter
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1

    sorted_colors = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    background = sorted_colors[0][0]
    special = sorted_colors[-1][0]

    result = [row[:] for row in grid]

    # Find anchor rows and columns
    anchor_rows = [r for r in range(h) if sum(1 for c in range(w) if grid[r][c] == special) >= 2]
    anchor_cols = [c for c in range(w) if sum(1 for r in range(h) if grid[r][c] == special) >= 2]

    # Find cells that are "anchor" (special cells that are part of anchor rows or cols)
    anchor_cells = set()
    for r in anchor_rows:
        for c in range(w):
            if grid[r][c] == special:
                anchor_cells.add((r, c))
    for c in anchor_cols:
        for r in range(h):
            if grid[r][c] == special:
                anchor_cells.add((r, c))

    # Fill anchor rows that have at least one special cell NOT at an anchor column
    for r in anchor_rows:
        row_nines = [c for c in range(w) if grid[r][c] == special]
        for c in row_nines:
            if (r, c) not in anchor_cells:  # At least one special cell not at anchor column
                # Fill horizontally
                for i in range(len(row_nines) - 1):
                    for cfill in range(row_nines[i] + 1, row_nines[i+1]):
                        if grid[r][cfill] == background:
                            result[r][cfill] = 2

    # Fill anchor columns that have at least one special cell NOT at an anchor row
    for c in anchor_cols:
        col_nines = [r for r in range(h) if grid[r][c] == special]
        for r in col_nines:
            if (r, c) not in anchor_cells:  # At least one special cell not at anchor row
                # Fill vertically
                for i in range(len(col_nines) - 1):
                    for rfill in range(col_nines[i] + 1, col_nines[i+1]):
                        if grid[rfill][c] == background:
                            result[rfill][c] = 2

    return result

