import json

def transform(grid):
    """FROZEN_TASK_8625f9bc: Fill between consecutive special cells in anchor lines"""
    from collections import Counter, defaultdict
    h = len(grid)
    w = len(grid[0]) if grid else 0

    if h * w == 0:
        return []

    counts = Counter(val for row in grid for val in row)
    background = max(counts, key=counts.get)
    special = min(counts, key=counts.get)

    grid_out = [row[:] for row in grid]

    row_special_count = defaultdict(list)
    col_special_count = defaultdict(list)
    special_pos = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == special:
                row_special_count[r].append(c)
                col_special_count[c].append(r)
                special_pos.add((r, c))

    anchor_rows = [r for r, cols in row_special_count.items() if len(cols) >= 2]
    anchor_cols = [c for c, rows in col_special_count.items() if len(rows) >= 2]

    intersection_cells = set((r, c) for r in anchor_rows for c in anchor_cols)
    intersection_cells = intersection_cells & special_pos

    anchor_rows_with_non_inter = [r for r in anchor_rows if any((r, c) not in intersection_cells for c in row_special_count[r])]
    anchor_cols_with_non_inter = [c for c in anchor_cols if any((r, c) not in intersection_cells for r in col_special_count[c])]

    for r in anchor_rows_with_non_inter:
        cols = row_special_count[r]
        for i in range(len(cols) - 1):
            start_c, end_c = cols[i], cols[i+1]
            if end_c - start_c > 1:
                for c in range(start_c + 1, end_c):
                    if grid_out[r][c] == background:
                        grid_out[r][c] = 2

    for c in anchor_cols_with_non_inter:
        rows = col_special_count[c]
        for i in range(len(rows) - 1):
            start_r, end_r = rows[i], rows[i+1]
            if end_r - start_r > 1:
                for r in range(start_r + 1, end_r):
                    if grid_out[r][c] == background:
                        grid_out[r][c] = 2

    return grid_out

